\begin{ex}%[8D2C4]
Tìm ${x}$ biết $3 x^{3} - 21 x - 18 =0 $
\choice
{ $x=1, x=2, x=3$  }
   { $x=-1, x=2, x=-3$  }
     { \True $x=-1, x=-2, x=3$  }
    {  $x=1, x=-2, x=3$ }
\loigiai{
$3 x^{3} - 21 x - 18 =3\left(x - 3\right) \left(x + 1\right) \left(x + 2\right)=0$ vậy $x=-1, x=-2, x=3$
}\end{ex}

